// Full business profiles. Generated by scripts/media/assemble.py from the
// verified research records in content/profiles/*.json plus the media
// manifests in public/media/<slug>/. Every fact carries a public source; media
// provenance (source URLs, clip timecodes, trace/original status) is kept in
// the reel/logo manifests and surfaced on each profile.
import data from "@/data/profiles.generated.json";

export interface ReelRendition {
  video: string;
  poster: string;
  posterWebp: string;
  width: number;
  height: number;
  durationSec: number;
  bytes: number;
}

export interface ReelSegment {
  sourceUrl: string;
  kind: "video" | "still";
  startSec?: number;
  endSec?: number;
  durationSec: number;
  note?: string;
}

export interface Reel {
  fade: number;
  audio: "stripped";
  segments: ReelSegment[];
  outputs: { desktop: ReelRendition; mobile: ReelRendition };
}

export interface Logo {
  src: string;
  /** svg-original: the business's own vector; svg-traced: our vector reconstruction of `sourceUrl`; raster: original bitmap. */
  kind: "svg-original" | "svg-traced" | "raster";
  sourceUrl: string;
  /** Background the mark needs to read well. */
  plate: "light" | "dark" | "none";
  width: number;
  height: number;
}

export interface GalleryImage {
  src: string;
  width: number;
  height: number;
  alt: string;
  sourceUrl: string;
}

export interface Profile {
  slug: string;
  displayName: string;
  tagline: string | null;
  intro: string;
  about: string[];
  services: { name: string; description: string; more?: string }[];
  /** Deeper verified detail from the business's own pages (content/profiles-extra). */
  extra: {
    highlights: string[];
    howItWorks: { title: string; text: string }[];
    goodToKnow: { text: string; sourceUrl: string }[];
    faqs: { q: string; a: string; sourceUrl: string }[];
  } | null;
  eventTypes: string[];
  areasServed: string[];
  website: string | null;
  socials: Partial<Record<"instagram" | "facebook" | "tiktok" | "youtube" | "vimeo", string>>;
  contact: { email: string | null; phone: string | null } | null;
  logo: Logo | null;
  /** 4:3 directory-card photo chosen from the business's own original-resolution uploads. */
  card: GalleryImage | null;
  gallery: GalleryImage[];
  reel: Reel | null;
  /** What the business itself says (overrides the 2025 directory listing on the profile). */
  established: { label: string; sourceUrl: string } | null;
  basedIn: { text: string; sourceUrl: string } | null;
  price: { text: string; sourceUrl: string } | null;
  /** Short form of `price` for directory cards. */
  cardPrice: { from: string; unit: string } | null;
  identity: { confidence: "high" | "medium" | "low" | "none"; note: string | null };
  sources: { label: string; url: string }[];
  gaps: string[];
}

const PROFILES = data as unknown as Record<string, Profile>;

export function getProfile(slug: string): Profile | undefined {
  return PROFILES[slug];
}
